package com.projexa.coaching.communication.controller;
import com.projexa.coaching.common.tenant.TenantContextHolder; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; import java.util.*;
@RestController @RequestMapping("/api/v1/communication") public class CommunicationController {private final JdbcTemplate db;public CommunicationController(JdbcTemplate db){this.db=db;}
 @PostMapping("/conversations") @PreAuthorize("hasAuthority('communication.send')") public Map<String,Object> create(@RequestBody CreateConversation req, Authentication auth){UUID t=TenantContextHolder.getRequired(); if(req.userIds()==null || req.userIds().isEmpty()) throw new IllegalArgumentException("At least one participant is required"); UUID caller=UUID.fromString(auth.getName()); List<UUID> participants=new ArrayList<>(req.userIds()); if(!participants.contains(caller)) participants.add(caller); for(UUID u:participants){Integer ok=db.queryForObject("select count(*) from users where id=? and tenant_id=? and status='ACTIVE'",Integer.class,u,t); if(ok==null||ok==0) throw new org.springframework.security.access.AccessDeniedException("Participant is not in this institute");} UUID c=UUID.randomUUID();db.update("insert into conversations(id,tenant_id,type,title) values(?,?,?,?)",c,t,req.type(),req.title());for(UUID u:participants)db.update("insert into conversation_members(conversation_id,user_id) values(?,?) on conflict do nothing",c,u);return Map.of("id",c);}
 @GetMapping("/conversations/{id}/messages") public List<Map<String,Object>> messages(@PathVariable UUID id, Authentication auth){UUID t=TenantContextHolder.getRequired(); Integer member=db.queryForObject("select count(*) from conversation_members cm join conversations c on c.id=cm.conversation_id where cm.conversation_id=? and cm.user_id=? and c.tenant_id=?",Integer.class,id,UUID.fromString(auth.getName()),t); if(member==null||member==0) throw new org.springframework.security.access.AccessDeniedException("Conversation is not accessible"); return db.queryForList("select m.* from messages m join conversations c on c.id=m.conversation_id where m.tenant_id=? and m.conversation_id=? order by m.created_at asc",t,id);}
 @PostMapping("/conversations/{id}/messages") public Map<String,Object> send(@PathVariable UUID id,@RequestBody SendMessage req, Authentication auth){UUID t=TenantContextHolder.getRequired();UUID sender=UUID.fromString(auth.getName()); Integer member=db.queryForObject("select count(*) from conversation_members cm join conversations c on c.id=cm.conversation_id where cm.conversation_id=? and cm.user_id=? and c.tenant_id=?",Integer.class,id,sender,t); if(member==null||member==0) throw new org.springframework.security.access.AccessDeniedException("Conversation is not accessible");UUID mid=UUID.randomUUID();db.update("insert into messages(id,tenant_id,conversation_id,sender_user_id,body) values(?,?,?,?,?)",mid,t,id,sender,req.body());return Map.of("id",mid,"createdAt",LocalDateTime.now());}
 public record CreateConversation(String type,String title,List<UUID> userIds){} public record SendMessage(String body){}
}
